/* Management views share state with the map; no duplicate economic model. */
(function(root){'use strict';
const S=root.YardSim,O=root.YardOperations,money=n=>Math.round(n).toLocaleString('ja-JP');
const presets=[{id:'flow',name:'組立を2並列',counts:[1,1,2,1],hint:'最初の観光車は組立が長い。ここを分けて流す。'}, {id:'lean',name:'小さく始める',counts:[1,1,1,1],hint:'固定費を抑え、人員の集中で流れを整える。'}, {id:'design',name:'設計を3並列',counts:[3,1,1,1],hint:'設計の長い近郊車や展望車に備える。'}, {id:'dual',name:'全工程を2並列',counts:[2,2,2,2],hint:'同時製造に強い。受注が少ないと固定費が重い。'}];
function moneyFlow(s){const t=s.tutorial?.step,phase=['layout','order','launch'].includes(t)?0:t==='watch'?1:t==='funding'?1:t==='manufacture'?2:['shipping','dispatch_wait'].includes(t)?3:4;
 return `<div class="money-flow" aria-label="受注から入金までのお金の流れ">${[
 ['受注','±0 G','約束だけ。入金なし'],['設計 → 材料発注','材料費 −','発注した瞬間に支払い'],['製造・運搬','給与・維持費 −','ゲーム時間ごとに支払い'],['出荷倉庫で保留','売上 0 G','納期まで出荷不可・保管料あり'],['納期の工場出荷','売上 ＋','この時点で初めて入金']
 ].map(([name,value,note],i)=>`<div class="money-step ${i===4?'monetize':''} ${t!=='done'&&i===phase?'current':''}"><span>${i+1}. ${name}</span><strong>${value}</strong><small>${note}</small></div>`).join('')}</div>`;
}
function funds(s){const f=O.finance(s),total=Math.max(1,s.cash),reserved=Math.min(100,f.commitment/total*100),reserve=Math.min(100-reserved,f.reserve/total*100);return `<section class="funds-board"><div class="funds-heading"><span>現金残高</span><strong>${money(f.cash)} <small>G</small></strong><span class="funds-note">完成品の売上見込は含みません</span></div><div class="funds-bar" aria-hidden="true"><i style="width:${reserved}%" class="committed"></i><i style="width:${reserve}%" class="reserve"></i><i style="flex:1" class="available"></i></div><div class="funds-breakdown"><div><span class="dot committed"></span>これからの材料費<b>${money(f.commitment)} G</b></div><div><span class="dot reserve"></span>60秒分の運営費目安<b>${money(f.reserve)} G</b></div><div><span class="dot available"></span>追加投資の目安<b>${money(f.available)} G</b></div></div><p class="tiny">運営費は現在の人員・設備・在庫で ${f.burn.toFixed(2)}G / ゲーム秒。将来の変化は含まない目安です。</p>${f.shortfall?`<p class="cash-warning">材料費と60秒分の運営費に ${money(f.shortfall)}G不足。納期前の完成品は換金できません。受注量・着工予約・投資を見直しましょう。</p>`:''}</section>`;}
function layout(s,counts){const setup=s.tutorial?.step==='layout',q=O.layoutQuote(s,counts),loads=O.loads(s);return `<p class="intro">${setup?'最初の工場は、あなたが編成します。1棟が1両ずつ加工するため、2棟なら2並列、3棟なら3並列。まずは組立を2並列にする編成を試してみましょう。':'実際の設備を増やすと同時に作れる両数が増えます。人員・維持費・次の工程の空きも一緒に確認しましょう。'}</p>
 ${setup?`<div class="layout-presets">${presets.map(p=>`<button class="preset ${p.counts.join()===counts.join()?'selected':''}" data-layout-preset="${p.id}" aria-pressed="${p.counts.join()===counts.join()}"><b>${p.name}</b><small>${p.hint}</small></button>`).join('')}</div>`:''}
 <div class="line-composer">${O.STAGES.map((type,i)=>{const n=setup?counts[i]:loads[i].count,l=loads[i],hires=Math.max(0,2-S.freeStaff(s)),cost=S.TYPES[type].cost+hires*350;return `<section class="line-column" style="--stage:${S.TYPES[type].color}"><h3>${i+1}. ${S.TYPES[type].short}</h3><div class="parallel-count">${n}<small>並列</small></div><div class="lane-slots">${Array.from({length:n},(_,a)=>`<div class="lane-slot"><b>${S.TYPES[type].short} ${a+1}</b><span>${setup?'2人配置':(l.bs[a]?.staff||0)+'人 · '+S.status(s,l.bs[a]).label}</span></div>`).join('')}</div>
 ${setup?`<label>並列数<select data-layout-stage="${i}" aria-label="${S.TYPES[type].short}の並列数">${[1,2,3].map(v=>`<option value="${v}" ${v===n?'selected':''}>${v}並列</option>`).join('')}</select></label>`:`<p>${l.waiting}両待ち · 能力 ${l.capacity.toFixed(2)}倍</p><button class="secondary full" data-action="parallel" data-id="${i}" ${n>=3||s.cash<=cost?'disabled':''}>${n>=3?'3並列以上':(n+1)+'並列へ · '+money(cost)+'G'}</button><small>${n<3?'設備＋不足する'+hires+'人の採用費。2人配置まで一括。':'さらに増やすには建設タブへ。'}</small>`}</section>`;}).join('')}</div>
 ${setup?`<div class="layout-quote"><div>設備総額<b>${money(q.equipment)} G</b><small>開業設備枠 ${money(q.grant)}G以内は現金負担なし</small></div><div>決定時の現金負担<b>${money(q.cost)} G</b></div><div>配置・給与対象<b>${q.employees}人</b><small>給与＋設備維持費 ${q.burn.toFixed(2)}G / 秒</small></div><div>開始時の現金<b>${money(q.remaining)} G</b></div></div><p class="tiny">開業設備枠の余りは現金になりません。開業後の増設は通常価格です。多い並列数ほど固定費が掛かり、少ない受注では利益を圧迫します。</p><button class="primary full" data-action="configure" ${q.ok?'':'disabled'}>この編成で工場を始める</button>${!q.ok?`<p class="cash-warning">${q.message}</p>`:''}`:`<div class="row-actions"><button class="primary" data-panel="staff">人員を調整</button><button class="secondary" data-panel="flow">受注の経路・着工を調整</button><button class="secondary" data-panel="build">建設場所を自分で選ぶ</button></div>${funds(s)}`}`;}
function shippingStrategy(s){
 const lesson=s.tutorial?.storageLesson,wait=lesson?Math.max(0,lesson.deadline-lesson.finishedAt):0,delay=Math.min(60,Math.floor(Math.max(0,wait-10)/10)*10);
 return `<section class="shipping-strategy"><h3>早すぎる完成を防ぐ、3つの戦略</h3><ol><li><b>着工を納期から逆算</b><span>生産計画 → 受注ごとの着工予約。設計・材料リードタイム・運搬・工程待ちに、遅れへの余裕も残します。</span></li><li><b>受注量と仕掛上限を絞る</b><span>遠い納期の案件を一斉に投入せず、出荷までの材料費・給与・維持費を現金で確保します。</span></li><li><b>応援・増設は遅れそうな工程へ</b><span>出荷倉庫に積み上がる完成品を増やすだけの加速は控えます。早く完成しても入金は早まりません。</span></li></ol>${lesson&&delay>0?`<div class="shipping-comparison"><div><span>今回の完成後の待ち</span><b>約${Math.round(wait)}秒 / 約${money(wait*.9)}G</b><small>納期まで売上は0G</small></div><div><span>着工を約${delay}秒遅らせた例</span><b>約${Math.round(wait-delay)}秒 / 約${money((wait-delay)*.9)}G</b><small>同じ納期・売上、保管費を約${money(delay*.9)}G削減</small></div></div><p class="tiny">この1両だけを同じ人員・経路で製造し、追加の故障や混雑がない場合の目安です。材料費の支払いも後ろへずれます。給与・維持費は待機中も必要で、着工を遅らせるだけでは減りません。</p>`:''}<button class="text-button" data-panel="flow">生産計画で着工予約を確認 →</button></section>`;
}
function shipping(s){const f=O.finance(s),jobs=s.jobs.filter(j=>j.status==='finished');return `<div class="shipping-hero"><span>出荷倉庫で保留</span><strong>${jobs.length} <small>両</small></strong><b>未入金の売上見込 ${money(f.uncollected)} G</b><p><strong>前倒し出荷はできません。</strong> 納期まで保管し、納期の工場出荷で初めて入金されます。</p></div>${jobs.map(j=>{const o=s.orders.find(o=>o.id===j.order),wait=Math.max(0,j.deadline-s.t);return `<article class="shipment-card"><div><h3>${S.PRODUCTS[j.product].name} · ${j.id.toUpperCase()}</h3><p class="deadline">納期の自動出荷まで あと${Math.ceil(wait)}秒</p><b>出荷時の売上 +${money(o.unitSale)}G / 現在は未入金</b><small>残りの保管費見込 ${(wait*.9).toFixed(2)}G（0.90G / 両・ゲーム秒）</small><small>給与・設備維持費は別途掛かります。</small></div><span class="shipment-locked">納期まで出荷不可</span></article>`;}).join('')||'<div class="empty-yard">完成品はまだありません。検査後の運搬が終わると到着します。納期を過ぎて到着した分は直ちに出荷し、遅延控除が発生します。</div>'}${moneyFlow(s)}${['shipping','debrief'].includes(s.tutorial?.step)?'':shippingStrategy(s)}<div class="row-actions"><button class="primary" data-panel="flow">次の着工予約を調整</button><button class="secondary" data-panel="finance">出荷までの資金を確認</button></div>`;}

function decision(s){if(!s.decision)return '';return `<section class="decision-card"><span class="eyebrow">あと ${Math.ceil(s.decision.expires-s.t)}秒で受付終了</span><h3>応援便が到着。何を早める？</h3><p>工程への応援は35秒間35%加速。資材の速達は到着待ちを最大12秒短縮。前後の工程も見て選ぼう。</p><div class="support-options">${O.loads(s).map(l=>`<button class="secondary" data-support="focus" data-stage="${l.stage}" ${s.cash<=220?'disabled':''}><b>${S.TYPES[l.type].short}へ応援</b><small>${l.waiting}両待ち · 220G</small></button>`).join('')}<button class="secondary" data-support="materials" ${s.cash<=180||!s.materials.some(l=>l.readyAt>s.t)?'disabled':''}><b>材料を速達</b><small>入荷待ち −12秒 · 180G</small></button><button class="text-button" data-support="pass">今回は見送る</button></div></section>`;}
function transactions(s){const names={revenue:'工場出荷の売上',materials:'材料の発注',capex:'設備・用地への投資',recovery:'設備の撤去回収',service:'採用・修理・応援など',freight:'旧ルールの出荷便費（履歴）',penalties:'納期遅延の控除',rewards:'助成・信頼ボーナス'};return `<h3>入出金のタイミング</h3><p class="tiny">発注・出荷・投資など直近24件。給与・維持費・保管料は毎ゲーム秒発生し、下の帳簿に集計します。</p><div class="cash-history">${(s.transactions||[]).map(t=>`<div><span>開始 ${t.t.toFixed(1)}秒<br><b>${names[t.category]||'その他'}</b></span><strong class="${t.amount>0?'cash-in':'cash-out'}">${t.amount>0?'+':'−'}${money(Math.abs(t.amount))} G</strong></div>`).join('')||'<p>まだ入出金はありません。</p>'}</div>`;}
function briefing(s){const guide=O.TUTORIAL[s.tutorial?.step];if(!guide)return '';const step=s.tutorial.step;return `<aside class="tutorial-panel"><span>チュートリアル ${guide.n} / 6</span><strong>${guide.title}</strong><p>${guide.body}</p>${['shipping','debrief'].includes(step)?shippingStrategy(s):''}${['launch','funding','shipping','debrief'].includes(step)?`<button class="primary full" data-action="tutorialContinue">${step==='launch'?'受注伝票を送って操業開始':step==='funding'?'材料到着・製造へ進む':step==='shipping'?'納期まで時間を進める ≫（保管費も精算）':'次の商談へ。着工予約を試してみる'}</button>`:''}${step==='layout'?'':`<button class="text-button" data-panel="${guide.panel}">${guide.cta}</button>`}</aside>`;}
root.YardManagement={presets,moneyFlow,funds,layout,shipping,shippingStrategy,decision,transactions,briefing};
})(typeof globalThis!=='undefined'?globalThis:this);
